Security Recommendation
Disable version disclosure in BIND:
# In named.conf.options
options {
    version "not disclosed";
}

En BIND, deshabilitar la exposición de versión:
# En named.conf.options
options {
    version "not disclosed";
}

sudo nmap -sC &lt;target&gt;



# Detección de vulnerabilidades
sudo nmap --script vuln &lt;target&gt;

# Enumeración HTTP
sudo nmap --script http-enum -p 80 &lt;target&gt;

# Banner grabbing
sudo nmap --script banner -p 21,22,80 &lt;target&gt;

# Enumeración SMB
nmap --script smb-enum-shares -p 445 &lt;target&gt;

# Enumeración SSH
nmap --script ssh-auth-methods -p 22 &lt;target&gt;

# Información DNS
nmap --script dns-brute &lt;domain&gt;

# Vulnerabilidades HTTP
nmap --script http-vuln* -p 80 &lt;target&gt;
